const item = $input.first().json;

const cleanEmail = (v) => (v || '').toString().trim().toLowerCase();
const cleanPhone = (v) => (v || '').toString().replace(/\D/g, '');
const cleanText = (v) => (v || '').toString().trim();

const recordType = cleanText(item.record_type).toLowerCase();
const now = new Date().toISOString();

const out = {
  ...item,
  record_type: recordType,
  source: cleanText(item.source) || 'webhook',
  city: cleanText(item.city),
  created_at: item.created_at || now,
  updated_at: now,

  // define these upfront so n8n type checker does not complain
  advisor_id: cleanText(item.advisor_id),
  lead_id: cleanText(item.lead_id),

  // keep as string because incoming schema treats it as string
  experience_years: cleanText(item.experience_years),
};

if (recordType === 'advisor') {
  out.advisor_name = cleanText(item.advisor_name);
  out.advisor_email = cleanEmail(item.advisor_email);
  out.advisor_phone = cleanPhone(item.advisor_phone);
  out.advisor_type = cleanText(item.advisor_type);
  out.specialization = cleanText(item.specialization);
  out.experience_years = cleanText(item.experience_years || '0');
  out.aum_range = cleanText(item.aum_range);
  out.client_type = cleanText(item.client_type);
  out.advisor_id = cleanText(item.advisor_id) || `ADV-${Date.now()}`;
}

if (recordType === 'lead') {
  out.lead_name = cleanText(item.lead_name);
  out.lead_email = cleanEmail(item.lead_email);
  out.lead_phone = cleanPhone(item.lead_phone);
  out.interest_area = cleanText(item.interest_area);
  out.budget_range = cleanText(item.budget_range);
  out.lead_id = cleanText(item.lead_id) || `LED-${Date.now()}`;
}

return [{ json: out }];

const incoming = $('Normalize Payload').first().json;
const rows = $input.all().map(i => i.json).filter(r => Object.keys(r || {}).length > 0);

const norm = (v) => String(v || '').trim().toLowerCase();
const toNum = (v, fallback = 0) => {
  const n = Number(v);
  return Number.isFinite(n) ? n : fallback;
};

let match = null;
for (const row of rows) {
  const rowEmail = norm(row.advisor_email);
  const rowPhone = String(row.advisor_phone || '').replace(/\D/g, '');
  const emailMatch = incoming.advisor_email && rowEmail && norm(incoming.advisor_email) === rowEmail;
  const phoneMatch = incoming.advisor_phone && rowPhone && String(incoming.advisor_phone || '').replace(/\D/g, '') === rowPhone;
  if (emailMatch || phoneMatch) {
    match = row;
    break;
  }
}

const advisorType = norm(incoming.advisor_type);
const specializationText = norm(incoming.specialization);
const clientType = norm(incoming.client_type);
const aumRange = norm(incoming.aum_range);
const experience = toNum(incoming.experience_years, 0);

const specializationList = specializationText
  .split(',')
  .map(s => s.trim())
  .filter(Boolean);

let score = 0;

// Role strength
if (advisorType.includes('wealth')) score += 18;
else if (advisorType.includes('investment')) score += 14;
else if (advisorType.includes('mutual')) score += 12;
else if (advisorType.includes('tax')) score += 10;
else score += 6;

// Specialization breadth and relevance
score += Math.min(specializationList.length, 4) * 6;
if (specializationText.includes('retirement')) score += 8;
if (specializationText.includes('sip')) score += 6;
if (specializationText.includes('tax')) score += 6;
if (specializationText.includes('wealth')) score += 8;
if (specializationText.includes('portfolio')) score += 6;

// Experience quality
if (experience >= 3) score += 8;
if (experience >= 5) score += 8;
if (experience >= 10) score += 8;
if (experience >= 15) score += 4;

// Client segment and AUM fit
if (clientType.includes('hni')) score += 10;
else if (clientType.includes('mixed')) score += 8;
else if (clientType.includes('retail')) score += 6;

if (aumRange.includes('10cr')) score += 16;
else if (aumRange.includes('5cr')) score += 14;
else if (aumRange.includes('1cr') || aumRange.includes('crore')) score += 12;
else if (aumRange.includes('50l') || aumRange.includes('25l')) score += 8;

// Data quality / operational readiness
if (incoming.city) score += 4;
if (incoming.advisor_email) score += 4;
if (incoming.advisor_phone) score += 4;
if (incoming.advisor_email && incoming.advisor_phone) score += 4;

score = Math.max(0, Math.min(100, Math.round(score)));

let advisor_grade = 'C';
let priority = 'Low';
let status = 'needs_review';

if (score >= 80) {
  advisor_grade = 'A';
  priority = 'High';
  status = 'high_value';
} else if (score >= 60) {
  advisor_grade = 'B';
  priority = 'Medium';
  status = 'qualified';
} else {
  advisor_grade = 'C';
  priority = 'Low';
  status = 'needs_review';
}

return [{
  json: {
    ...incoming,
    is_duplicate: !!match,
    duplicate_flag: !!match ? 'yes' : 'no',
    existing_advisor_id: match?.advisor_id || null,
    existing_created_at: match?.created_at || incoming.created_at || null,
    active_leads_count: Number(match?.active_leads_count || 0),
    max_capacity: Number(match?.max_capacity || 10),
    availability_status: match?.availability_status || 'available',
    wealth_score: score,
    advisor_grade,
    priority,
    status
  }
}];

const base = $('Check Duplicate And Score Advisor').first().json;

let raw =
  $input.first().json.text ||
  $input.first().json.response ||
  $input.first().json.content ||
  '{}';

if (typeof raw === 'string') {
  raw = raw.trim();
  raw = raw.replace(/^```json\s*/i, '');
  raw = raw.replace(/^```/, '');
  raw = raw.replace(/```$/, '');
  raw = raw.trim();
}

let parsed = {};
try {
  parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch (e) {
  parsed = {};
}

const norm = (v) => String(v || '').trim();
const normLower = (v) => String(v || '').trim().toLowerCase();
const uniq = (arr) => [...new Set(arr.filter(Boolean))];

const keywordMap = [
  ['retirement', 'retirement_planning'],
  ['sip', 'sip'],
  ['mutual', 'mutual_funds'],
  ['tax', 'tax_planning'],
  ['wealth', 'wealth_management'],
  ['portfolio', 'portfolio_management'],
  ['stock', 'stock_investing'],
  ['equity', 'stock_investing'],
  ['insurance', 'insurance'],
  ['goal', 'goal_planning'],
  ['estate', 'estate_planning']
];

const toSpecializations = (value) => {
  if (Array.isArray(value)) return uniq(value.map(v => normLower(v)));
  const text = normLower(value);
  if (!text) return [];
  const tags = [];
  for (const [needle, tag] of keywordMap) {
    if (text.includes(needle)) tags.push(tag);
  }
  return uniq(tags.length ? tags : text.split(',').map(s => s.trim()).filter(Boolean));
};

const rawSpecs = toSpecializations(parsed.normalized_specializations);
const fallbackSpecs = toSpecializations(base.specialization);
const normalizedSpecializations = uniq(rawSpecs.length ? rawSpecs : fallbackSpecs);

const advisorCategory = norm(parsed.advisor_category) || (
  normLower(base.advisor_type).includes('retirement') ? 'Retirement Advisor' :
  normLower(base.advisor_type).includes('mutual') ? 'Mutual Fund Advisor' :
  normLower(base.advisor_type).includes('tax') ? 'Tax Advisor' :
  normLower(base.advisor_type).includes('investment') ? 'Investment Advisor' :
  normLower(base.advisor_type).includes('insurance') ? 'Insurance Advisor' :
  normLower(base.advisor_type).includes('wealth') ? 'Wealth Advisor' :
  'General Advisor'
);

const clientSegmentFocus = ['HNI', 'Retail', 'Mixed'].includes(parsed.client_segment_focus)
  ? parsed.client_segment_focus
  : (normLower(base.client_type).includes('hni') ? 'HNI' : normLower(base.client_type).includes('retail') ? 'Retail' : 'Mixed');

const serviceTier = ['Premium', 'Standard', 'Entry'].includes(parsed.service_tier)
  ? parsed.service_tier
  : (Number(base.wealth_score || 0) >= 80 ? 'Premium' : Number(base.wealth_score || 0) >= 60 ? 'Standard' : 'Entry');

const idealBudgetBand = ['High', 'Mid', 'Standard'].includes(parsed.ideal_budget_band)
  ? parsed.ideal_budget_band
  : (
      normLower(base.aum_range).includes('10cr') || normLower(base.aum_range).includes('5cr') || normLower(base.client_type).includes('hni')
        ? 'High'
        : normLower(base.aum_range).includes('1cr') || normLower(base.aum_range).includes('50l')
        ? 'Mid'
        : 'Standard'
    );

const serviceRegions = uniq(
  (Array.isArray(parsed.service_regions) ? parsed.service_regions : [parsed.service_regions, base.city])
    .map(v => norm(v))
    .filter(Boolean)
);

const profile = {
  advisor_category: advisorCategory,
  normalized_specializations: normalizedSpecializations,
  client_segment_focus: clientSegmentFocus,
  service_tier: serviceTier,
  ideal_budget_band: idealBudgetBand,
  service_regions: serviceRegions,
  intake_quality: ['Strong', 'Moderate', 'Basic'].includes(parsed.intake_quality) ? parsed.intake_quality : (Number(base.wealth_score || 0) >= 75 ? 'Strong' : Number(base.wealth_score || 0) >= 55 ? 'Moderate' : 'Basic')
};

const originalNotes = norm(base.notes);
const profileBlock = `PROFILE::${JSON.stringify(profile)}`;
const notes = originalNotes
  ? (originalNotes.includes('PROFILE::') ? originalNotes.replace(/PROFILE::\{.*\}$/s, profileBlock) : `${originalNotes}\n${profileBlock}`)
  : profileBlock;

return [{
  json: {
    advisor_id: base.existing_advisor_id || base.advisor_id,
    advisor_name: base.advisor_name,
    advisor_email: base.advisor_email,
    advisor_phone: base.advisor_phone,
    city: base.city,
    advisor_type: advisorCategory,
    specialization: normalizedSpecializations.join(', '),
    experience_years: Number(base.experience_years || 0),
    aum_range: base.aum_range,
    client_type: clientSegmentFocus,
    wealth_score: Number(base.wealth_score || 0),
    advisor_grade: base.advisor_grade,
    priority: base.priority,
    status: base.status,
    ai_summary: parsed.ai_summary || 'Advisor profile standardized and ready for lead assignment.',
    next_action: parsed.next_action || 'Review advisor capacity and activate for matching.',
    source: base.source,
    created_at: base.existing_created_at || base.created_at || new Date().toISOString(),
    updated_at: new Date().toISOString(),
    duplicate_flag: base.duplicate_flag,
    notes,
    active_leads_count: Number(base.active_leads_count || 0),
    max_capacity: Number(base.max_capacity || 10),
    availability_status: base.availability_status || 'available'
  }
}];

const incoming = $('Normalize Payload').first().json;
const rows = $input.all().map(i => i.json).filter(r => Object.keys(r || {}).length > 0);

const norm = (v) => String(v || '').trim().toLowerCase();

let match = null;
for (const row of rows) {
  const rowEmail = norm(row.lead_email);
  const rowPhone = String(row.lead_phone || '').replace(/\D/g, '');
  const emailMatch = incoming.lead_email && rowEmail && norm(incoming.lead_email) === rowEmail;
  const phoneMatch = incoming.lead_phone && rowPhone && String(incoming.lead_phone || '').replace(/\D/g, '') === rowPhone;
  if (emailMatch || phoneMatch) {
    match = row;
    break;
  }
}

const interest = norm(incoming.interest_area);
const budget = norm(incoming.budget_range);
const source = norm(incoming.source);

let score = 0;

// Intent richness
if (interest.includes('retirement')) score += 18;
if (interest.includes('sip')) score += 12;
if (interest.includes('wealth')) score += 14;
if (interest.includes('tax')) score += 10;
if (interest.includes('portfolio')) score += 10;
if (interest.includes('investment')) score += 12;

// Buying power / potential
if (budget.includes('1cr') || budget.includes('crore')) score += 30;
else if (budget.includes('50l')) score += 24;
else if (budget.includes('25l')) score += 18;
else if (budget.includes('10l')) score += 12;

// Data quality
if (incoming.city) score += 8;
if (incoming.lead_email) score += 8;
if (incoming.lead_phone) score += 8;
if (incoming.lead_email && incoming.lead_phone) score += 6;

// Source quality
if (source.includes('referral')) score += 14;
else if (source.includes('campaign')) score += 10;
else if (source.includes('website')) score += 6;

score = Math.max(0, Math.min(100, Math.round(score)));

let lead_grade = 'C';
let priority = 'Low';
let status = 'needs_review';

if (score >= 75) {
  lead_grade = 'A';
  priority = 'High';
  status = 'qualified';
} else if (score >= 50) {
  lead_grade = 'B';
  priority = 'Medium';
  status = 'qualified';
}

return [{
  json: {
    ...incoming,
    is_duplicate: !!match,
    duplicate_flag: !!match ? 'yes' : 'no',
    existing_lead_id: match?.lead_id || null,
    existing_created_at: match?.created_at || incoming.created_at || null,
    interaction_count: Number(match?.interaction_count || 0) + 1,
    lead_score: score,
    lead_grade,
    priority,
    status
  }
}];

const base = $('Check Duplicate And Score Lead').first().json;
const advisors = $('Read Advisors For Assignment').all().map(i => i.json).filter(r => Object.keys(r || {}).length > 0);
const aiNode = $('AI Summarize Lead').first().json;

let raw = aiNode.text || aiNode.response || aiNode.content || '{}';
if (typeof raw === 'string') {
  raw = raw.trim();
  raw = raw.replace(/^```json\s*/i, '');
  raw = raw.replace(/^```/, '');
  raw = raw.replace(/```$/, '');
  raw = raw.trim();
}

let parsed = {};
try {
  parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch (e) {
  parsed = {};
}

const norm = (v) => String(v || '').trim().toLowerCase();
const toNum = (v, fallback = 0) => {
  const n = Number(v);
  return Number.isFinite(n) ? n : fallback;
};
const uniq = (arr) => [...new Set(arr.filter(Boolean))];

const keywordMap = [
  ['retirement', 'retirement_planning'],
  ['sip', 'sip'],
  ['mutual', 'mutual_funds'],
  ['tax', 'tax_planning'],
  ['wealth', 'wealth_management'],
  ['portfolio', 'portfolio_management'],
  ['stock', 'stock_investing'],
  ['equity', 'stock_investing'],
  ['insurance', 'insurance'],
  ['goal', 'goal_planning'],
  ['investment', 'general_investment']
];

const normalizeNeed = (value) => {
  const text = norm(value);
  if (!text) return [];
  const tags = [];
  for (const [needle, tag] of keywordMap) {
    if (text.includes(needle)) tags.push(tag);
  }
  return uniq(tags);
};

const parseProfileFromNotes = (notes) => {
  const text = String(notes || '');
  const match = text.match(/PROFILE::(\{.*\})/s);
  if (!match) return {};
  try {
    return JSON.parse(match[1]);
  } catch (e) {
    return {};
  }
};

const primaryNeed = String(parsed.primary_need || '').trim() || (normalizeNeed(base.interest_area)[0] || 'general_investment');
const secondaryNeeds = Array.isArray(parsed.secondary_needs) ? parsed.secondary_needs.map(v => String(v).trim()).filter(Boolean) : [];
const leadNeeds = uniq([primaryNeed, ...secondaryNeeds, ...normalizeNeed(base.interest_area)]);
const leadCity = norm(base.city);
const budgetBand = ['High', 'Mid', 'Standard'].includes(parsed.budget_band)
  ? parsed.budget_band
  : (
      norm(base.budget_range).includes('1cr') || norm(base.budget_range).includes('crore')
        ? 'High'
        : norm(base.budget_range).includes('50l') || norm(base.budget_range).includes('25l')
        ? 'Mid'
        : 'Standard'
    );

const leadSegment = ['HNI', 'Affluent', 'Retail'].includes(parsed.lead_segment)
  ? parsed.lead_segment
  : (budgetBand === 'High' ? 'HNI' : budgetBand === 'Mid' ? 'Affluent' : 'Retail');

const allowedStatuses = ['qualified', 'high_value', 'active', 'approved'];
const scoredCandidates = [];
const fallbackCandidates = [];

for (const adv of advisors) {
  const status = norm(adv.status || 'active');
  const availability = norm(adv.availability_status || 'available');
  const activeLeads = toNum(adv.active_leads_count, 0);
  const maxCapacity = Math.max(toNum(adv.max_capacity, 10), 1);

  if (availability !== 'available') continue;
  if (status && !allowedStatuses.includes(status)) continue;
  if (activeLeads >= maxCapacity) continue;

  const profile = parseProfileFromNotes(adv.notes);
  const advisorCategory = String(profile.advisor_category || adv.advisor_type || '').trim();
  const specializationTags = uniq(
    Array.isArray(profile.normalized_specializations)
      ? profile.normalized_specializations.map(v => String(v).trim()).filter(Boolean)
      : String(adv.specialization || '')
          .split(',')
          .map(s => s.trim())
          .filter(Boolean)
          .flatMap(normalizeNeed)
  );
  const clientSegmentFocus = String(profile.client_segment_focus || adv.client_type || 'Mixed').trim();
  const serviceTier = String(profile.service_tier || '').trim() || (toNum(adv.wealth_score) >= 80 ? 'Premium' : toNum(adv.wealth_score) >= 60 ? 'Standard' : 'Entry');
  const idealBudgetBand = String(profile.ideal_budget_band || '').trim() || (clientSegmentFocus === 'HNI' ? 'High' : clientSegmentFocus === 'Mixed' ? 'Mid' : 'Standard');
  const advisorCity = norm(adv.city);
  const utilization = activeLeads / maxCapacity;
  const advisorScore = Math.max(0, Math.min(100, toNum(adv.wealth_score)));

  let semanticScore = 0;
  const reasons = [];
  const overlap = leadNeeds.filter(tag => specializationTags.includes(tag));

  if (overlap.length) {
    semanticScore += overlap.includes(primaryNeed) ? 40 : 0;
    semanticScore += overlap.filter(tag => tag !== primaryNeed).length * 12;
    reasons.push(`Need match: ${overlap.join(', ')}`);
  }

  const categoryNeedMap = {
    'Wealth Advisor': ['wealth_management', 'general_investment', 'goal_planning', 'portfolio_management'],
    'Retirement Advisor': ['retirement_planning', 'goal_planning', 'wealth_management'],
    'Mutual Fund Advisor': ['mutual_funds', 'sip', 'general_investment'],
    'Tax Advisor': ['tax_planning'],
    'Investment Advisor': ['stock_investing', 'portfolio_management', 'general_investment'],
    'Insurance Advisor': ['insurance', 'goal_planning'],
    'General Advisor': ['general_investment', 'goal_planning']
  };

  if ((categoryNeedMap[advisorCategory] || []).includes(primaryNeed)) {
    semanticScore += 18;
    reasons.push(`Advisor category fit: ${advisorCategory}`);
  }

  let geographyScore = 0;
  if (leadCity && advisorCity && leadCity === advisorCity) {
    geographyScore += 12;
    reasons.push('City match');
  } else if (!advisorCity) {
    geographyScore += 4;
  }

  let segmentScore = 0;
  if (leadSegment === 'HNI' && clientSegmentFocus === 'HNI') {
    segmentScore += 18;
    reasons.push('HNI segment fit');
  } else if (leadSegment === 'HNI' && clientSegmentFocus === 'Mixed') {
    segmentScore += 10;
  } else if (leadSegment === 'Affluent' && ['Mixed', 'HNI', 'Retail'].includes(clientSegmentFocus)) {
    segmentScore += clientSegmentFocus === 'Mixed' ? 14 : 10;
    reasons.push('Affluent segment fit');
  } else if (leadSegment === 'Retail' && ['Retail', 'Mixed'].includes(clientSegmentFocus)) {
    segmentScore += clientSegmentFocus === 'Retail' ? 14 : 10;
    reasons.push('Retail segment fit');
  }

  let budgetScore = 0;
  if (budgetBand === idealBudgetBand) {
    budgetScore += 14;
    reasons.push(`Budget fit: ${budgetBand}`);
  } else if (budgetBand === 'High' && serviceTier === 'Premium') {
    budgetScore += 12;
  } else if (budgetBand === 'Mid' && ['Premium', 'Standard'].includes(serviceTier)) {
    budgetScore += 10;
  } else if (budgetBand === 'Standard') {
    budgetScore += 8;
  }

  const experienceScore = Math.min(toNum(adv.experience_years, 0), 15) * 0.5;
  const qualityScore = advisorScore * 0.08;
  const loadScore = Math.max(0, (1 - utilization) * 10);

  const totalScore = semanticScore + geographyScore + segmentScore + budgetScore + experienceScore + qualityScore + loadScore;

  const candidate = {
    advisor: adv,
    totalScore,
    semanticScore,
    reasons,
    activeLeads,
    maxCapacity
  };

  if (semanticScore > 0 || segmentScore >= 10) {
    scoredCandidates.push(candidate);
  } else {
    fallbackCandidates.push(candidate);
  }
}

const orderedCandidates = (scoredCandidates.length ? scoredCandidates : fallbackCandidates)
  .sort((a, b) => b.totalScore - a.totalScore || a.activeLeads - b.activeLeads || b.advisor.wealth_score - a.advisor.wealth_score);

const selected = orderedCandidates[0] || null;
const best = selected?.advisor || null;
const bestScore = selected ? Math.round(selected.totalScore) : 0;
const matchReason = selected?.reasons?.length ? selected.reasons.join(' | ') : (best ? 'Assigned using fallback availability and quality rules' : 'No eligible advisor available');

const followUpDate = new Date();
const effectiveUrgency = ['High', 'Medium', 'Low'].includes(parsed.urgency)
  ? parsed.urgency
  : (base.priority === 'High' ? 'High' : base.priority === 'Medium' ? 'Medium' : 'Low');

if (effectiveUrgency === 'High') followUpDate.setDate(followUpDate.getDate() + 1);
else if (effectiveUrgency === 'Medium') followUpDate.setDate(followUpDate.getDate() + 2);
else followUpDate.setDate(followUpDate.getDate() + 4);

const wealthScore = Math.max(0, Math.min(100, toNum(parsed.wealth_score ?? base.lead_score, 0)));
const investmentPotential = ['High', 'Medium', 'Low'].includes(parsed.investment_potential)
  ? parsed.investment_potential
  : (base.priority === 'High' ? 'High' : base.priority === 'Medium' ? 'Medium' : 'Low');

return [{
  json: {
    lead_id: base.existing_lead_id || base.lead_id,
    lead_name: base.lead_name,
    lead_email: base.lead_email,
    lead_phone: base.lead_phone,
    city: base.city,
    interest_area: base.interest_area,
    budget_range: base.budget_range,
    lead_source: base.source,
    lead_score: Number(base.lead_score || 0),
    wealth_score: wealthScore,
    investment_potential: investmentPotential,
    lead_grade: base.lead_grade,
    priority: base.priority,
    priority_queue_rank: base.priority === 'High' ? 1 : base.priority === 'Medium' ? 2 : 3,
    status: best ? 'assigned' : base.status,
    assigned_advisor_id: best?.advisor_id || '',
    assigned_advisor_name: best?.advisor_name || '',
    assigned_advisor_email: best?.advisor_email || '',
    advisor_match_score: bestScore,
    urgency: effectiveUrgency,
    intent: primaryNeed,
    ai_summary: parsed.ai_summary || 'Lead scored successfully and is ready for advisor review.',
    next_action: parsed.next_action || (best ? 'Assigned to the best-fit available advisor based on need, segment, capacity, and city.' : 'No eligible advisor found. Review manually and assign.'),
    next_action_date: followUpDate.toISOString().slice(0, 10),
    follow_up_required: 'yes',
    last_contacted_at: '',
    created_at: base.existing_created_at || base.created_at || new Date().toISOString(),
    updated_at: new Date().toISOString(),
    duplicate_flag: base.duplicate_flag,
    notes: [base.notes, `ASSIGNMENT_REASON::${matchReason}`].filter(Boolean).join('\n'),
    interaction_count: Number(base.interaction_count || 1),
    assigned_advisor_reason: matchReason
  }
}];

const today = new Date().toISOString().slice(0, 10);

const items = $input.all()
  .map(i => i.json)
  .filter(row =>
    String(row.follow_up_required || '').toLowerCase() === 'yes' &&
    !!row.next_action_date &&
    String(row.next_action_date).slice(0, 10) <= today &&
    !!String(row.lead_email || '').trim() &&
    !!String(row.assigned_advisor_email || '').trim() &&
    !!String(row.assigned_advisor_name || '').trim()
  )
  .map(row => {
    const leadName = String(row.lead_name || 'there').trim();
    const advisorName = String(row.assigned_advisor_name || 'your advisor').trim();
    const interestArea = String(row.interest_area || 'financial planning').trim();
    const nextAction = String(row.next_action || 'Please review the next step.').trim();
    const nextActionDate = String(row.next_action_date || '').trim();
    const urgency = String(row.urgency || 'Medium').trim();
    const city = String(row.city || '').trim();
    const budgetRange = String(row.budget_range || '').trim();
    const leadEmail = String(row.lead_email || '').trim();
    const advisorEmail = String(row.assigned_advisor_email || '').trim();
    const notes = String(row.notes || '').trim();

    const leadSubject = `Follow-up on your ${interestArea}`;
    const leadBody = `Hi ${leadName},

I am following up regarding your interest in ${interestArea}.

Your assigned advisor is ${advisorName}.
Recommended next step: ${nextAction}
Scheduled follow-up date: ${nextActionDate}

Please reply to this email if you would like to continue, and we will assist you with the next steps.

Regards,
${advisorName}`;

    const advisorSubject = `Follow-up action due: ${leadName} (${interestArea})`;
    const advisorBody = `Hi ${advisorName},

A lead follow-up is due now.

Lead details:
Name: ${leadName}
Email: ${leadEmail}
City: ${city}
Interest Area: ${interestArea}
Budget Range: ${budgetRange}
Urgency: ${urgency}

Recommended next step:
${nextAction}

Scheduled follow-up date:
${nextActionDate}

Notes:
${notes}

Please contact the lead and update the CRM after action is taken.`;

    return {
      json: {
        ...row,
        lead_followup_to: leadEmail,
        lead_followup_subject: leadSubject,
        lead_followup_body: leadBody,
        advisor_followup_to: advisorEmail,
        advisor_followup_subject: advisorSubject,
        advisor_followup_body: advisorBody,
        followup_run_date: today,
        followup_status: 'ready_to_send'
      }
    };
  });

return items;

const now = new Date().toISOString();

return $input.all().map(item => {
  const row = item.json;

  const existingNotes = String(row.notes || '').trim();
  const reminderLine = `FOLLOWUP_REMINDER_SENT::${now}`;

  return {
    json: {
      lead_id: row.lead_id,
      updated_at: now,
      notes: existingNotes
        ? `${existingNotes}\n${reminderLine}`
        : reminderLine
    }
  };
});

const leads = $('Read Leads For Dashboard').all().map(i => i.json).filter(r => Object.keys(r || {}).length > 0);
const advisors = $('Read Advisors For Dashboard').all().map(i => i.json).filter(r => Object.keys(r || {}).length > 0);
const today = new Date().toISOString().slice(0, 10);

const total_leads = leads.length;
const new_leads_today = leads.filter(x => String(x.created_at || '').slice(0, 10) === today).length;
const high_priority_leads = leads.filter(x => String(x.priority || '') === 'High').length;
const assigned_leads = leads.filter(x => String(x.status || '').toLowerCase() === 'assigned').length;
const followups_due_today = leads.filter(x =>
  String(x.follow_up_required || '').toLowerCase() === 'yes' &&
  !!x.next_action_date &&
  String(x.next_action_date).slice(0, 10) <= today
).length;

const total_advisors = advisors.length;
const available_advisors = advisors.filter(x => String(x.availability_status || '').toLowerCase() === 'available').length;
const high_value_advisors = advisors.filter(x => String(x.status || '').toLowerCase() === 'high_value').length;

return [{
  json: {
    dashboard_id: `DASH-${Date.now()}`,
    dashboard_date: today,
    total_leads,
    new_leads_today,
    high_priority_leads,
    assigned_leads,
    followups_due_today,
    total_advisors,
    available_advisors,
    high_value_advisors,
    updated_at: new Date().toISOString()
  }
}];

const x = $input.first().json;
return [{
  json: {
    log_id: `LOG-${Date.now()}`,
    record_type: 'advisor',
    record_id: x.advisor_id || '',
    action_type: (x.duplicate_flag || '').toLowerCase() === 'yes' ? 'Advisor Updated' : 'Advisor Created',
    action_details: `Score: ${x.wealth_score || ''} | Grade: ${x.advisor_grade || ''} | Priority: ${x.priority || ''} | Status: ${x.status || ''}`,
    timestamp: new Date().toISOString(),
    workflow_name: 'Webhook Lead & Advisor CRM with AI Scoring, Assignment and Follow-Up'
  }
}];

const x = $input.first().json;
return [{
  json: {
    log_id: `LOG-${Date.now()}`,
    record_type: 'lead',
    record_id: x.lead_id || '',
    action_type: (x.duplicate_flag || '').toLowerCase() === 'yes' ? 'Lead Updated' : 'Lead Created',
    action_details: `Wealth Score: ${x.wealth_score || x.lead_score || ''} | Investment Potential: ${x.investment_potential || x.priority || ''} | Assigned Advisor: ${x.assigned_advisor_name || 'None'} | Match: ${x.assigned_advisor_reason || 'N/A'}`,
    timestamp: new Date().toISOString(),
    workflow_name: 'Webhook Lead & Advisor CRM with AI Scoring, Assignment and Follow-Up'
  }
}];

const body = $json.body || $json;

const cleanText = (v) => String(v ?? '').trim();
const cleanEmail = (v) => String(v ?? '').trim().toLowerCase();
const yesNo = (v) => {
  const t = cleanText(v).toLowerCase();
  if (['yes','true','1','required','y'].includes(t)) return 'yes';
  if (['no','false','0','not_required','n'].includes(t)) return 'no';
  return 'yes';
};

const leadId = cleanText(body.lead_id);
if (!leadId) throw new Error('lead_id is required');

const now = new Date().toISOString();

return [{
  json: {
    lead_id: leadId,
    advisor_id: cleanText(body.advisor_id),
    advisor_name: cleanText(body.advisor_name || body.assigned_advisor_name),
    advisor_email: cleanEmail(body.advisor_email),
    contact_status: cleanText(body.contact_status || body.status || 'followup_updated'),
    follow_up_required: yesNo(body.follow_up_required),
    next_action: cleanText(body.next_action || 'Advisor updated the follow-up plan.'),
    next_action_date: cleanText(body.next_action_date),
    lead_status: cleanText(body.lead_status || (yesNo(body.follow_up_required) === 'no' ? 'engaged' : 'assigned')),
    last_contacted_at: cleanText(body.last_contacted_at || now),
    update_note: cleanText(body.update_note || body.notes || body.outcome || ''),
    updated_at: now
  }
}];

